import { View, Text, TextInput, FlatList, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "1", name: "Чихэвч" },
  { id: "2", name: "Гар цаг" },
  { id: "3", name: "Нарны шил" },
  { id: "4", name: "Цүнх" },
  { id: "5", name: "Гар чийдэн" },
];

function App() {
  const [q, setQ] = useState("");
  // энд бичнэ үү: q-гээр PRODUCTS-ийг шүү
  const filtered = PRODUCTS;

  return (
    <View style={styles.screen}>
      <TextInput nativeID="search" style={styles.input} placeholder="Хайх..." value={q} onChangeText={setQ} />
      <FlatList
        data={filtered}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => <Text testID="row" style={styles.row}>{item.name}</Text>}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f5f6f8", padding: 8 },
  input: { borderWidth: 1, borderColor: "#d4d4d8", borderRadius: 12, padding: 12, margin: 8, fontSize: 16, backgroundColor: "#fff" },
  row: { backgroundColor: "#ffffff", padding: 16, margin: 8, borderRadius: 12, fontSize: 16 },
});

registerRootComponent(App);

import { View, Text, TextInput, FlatList, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "1", name: "Чихэвч" },
  { id: "2", name: "Гар цаг" },
  { id: "3", name: "Нарны шил" },
  { id: "4", name: "Цүнх" },
  { id: "5", name: "Гар чийдэн" },
];

function App() {
  const [q, setQ] = useState("");
  const filtered = PRODUCTS.filter((p) =>
    p.name.toLowerCase().includes(q.toLowerCase())
  );

  return (
    <View style={styles.screen}>
      <TextInput nativeID="search" style={styles.input} placeholder="Хайх..." value={q} onChangeText={setQ} />
      <FlatList
        data={filtered}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => <Text testID="row" style={styles.row}>{item.name}</Text>}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f5f6f8", padding: 8 },
  input: { borderWidth: 1, borderColor: "#d4d4d8", borderRadius: 12, padding: 12, margin: 8, fontSize: 16, backgroundColor: "#fff" },
  row: { backgroundColor: "#ffffff", padding: 16, margin: 8, borderRadius: 12, fontSize: 16 },
});

registerRootComponent(App);
